package fetchall

import (
	"context"
	"errors"
	"sync"
)

// Result holds one successfully processed input's output.
type Result struct {
	Index  int    // position of the input that produced this output
	Output string
}

// Process runs operation on each input with at most concurrency in-flight
// operations. Results are returned ordered by Index ascending. On failure it
// still runs every operation and aggregates every individual error so that
// each remains reachable via errors.Is / errors.As.
func Process(
	ctx context.Context,
	inputs []string,
	concurrency int,
	operation func(ctx context.Context, input string) (string, error),
) ([]Result, error) {
	if concurrency < 1 {
		return nil, errors.New("fetchall: concurrency must be at least 1")
	}
	if len(inputs) == 0 {
		return nil, nil
	}

	sem := make(chan struct{}, concurrency)
	outputs := make([]string, len(inputs))
	errs := make([]error, len(inputs))

	var wg sync.WaitGroup
	for i, input := range inputs {
		i, input := i, input
		sem <- struct{}{} // acquire — blocks when at capacity
		wg.Go(func() {
			defer func() { <-sem }() // release
			out, err := operation(ctx, input)
			outputs[i] = out
			errs[i] = err
		})
	}
	wg.Wait()

	var results []Result
	var joined error
	for i := range outputs {
		if errs[i] != nil {
			joined = errors.Join(joined, errs[i])
		} else {
			results = append(results, Result{Index: i, Output: outputs[i]})
		}
	}
	return results, joined
}

package fetchall

import (
	"context"
	"errors"
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

// sentinel error for testing reachability via errors.Is.
var errSentinel = errors.New("sentinel")

type customError struct {
	msg string
}

func (e *customError) Error() string { return e.msg }

func TestProcess_EmptyInputs(t *testing.T) {
	t.Parallel()
	results, err := Process(context.Background(), nil, 5, nil)
	if results != nil || err != nil {
		t.Fatalf("nil inputs: expected (nil, nil), got (%v, %v)", results, err)
	}
	results, err = Process(context.Background(), []string{}, 5, nil)
	if results != nil || err != nil {
		t.Fatalf("empty inputs: expected (nil, nil), got (%v, %v)", results, err)
	}
}

func TestProcess_InvalidConcurrency(t *testing.T) {
	t.Parallel()
	_, err := Process(context.Background(), []string{"a"}, 0, nil)
	if err == nil {
		t.Fatal("expected error for concurrency=0")
	}
	_, err = Process(context.Background(), []string{"a"}, -1, nil)
	if err == nil {
		t.Fatal("expected error for concurrency=-1")
	}
}

func TestProcess_Success(t *testing.T) {
	t.Parallel()
	inputs := []string{"a", "b", "c", "d", "e"}
	results, err := Process(context.Background(), inputs, 2,
		func(ctx context.Context, s string) (string, error) {
			return s + "!", nil
		})
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(results) != len(inputs) {
		t.Fatalf("got %d results, want %d", len(results), len(inputs))
	}
	for i, r := range results {
		if r.Index != i {
			t.Errorf("result %d has Index=%d, want %d", i, r.Index, i)
		}
		if r.Output != inputs[i]+"!" {
			t.Errorf("result %d has Output=%q, want %q", i, r.Output, inputs[i]+"!")
		}
	}
}

func TestProcess_ResultsOrderedByIndex(t *testing.T) {
	t.Parallel()
	// Operations take variable time so they finish out of order.
	inputs := []string{"slow", "fast", "medium"}
	var mu sync.Mutex
	delays := map[string]time.Duration{
		"slow":   50 * time.Millisecond,
		"fast":   5 * time.Millisecond,
		"medium": 20 * time.Millisecond,
	}
	results, err := Process(context.Background(), inputs, 3,
		func(ctx context.Context, s string) (string, error) {
			mu.Lock()
			d := delays[s]
			mu.Unlock()
			time.Sleep(d)
			return s, nil
		})
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(results) != 3 {
		t.Fatalf("got %d results, want 3", len(results))
	}
	for i, r := range results {
		if r.Index != i {
			t.Errorf("result %d has Index=%d, want %d", i, r.Index, i)
		}
		if r.Output != inputs[i] {
			t.Errorf("result %d has Output=%q, want %q", i, r.Output, inputs[i])
		}
	}
}

func TestProcess_PartialFailures(t *testing.T) {
	t.Parallel()
	inputs := []string{"ok1", "fail1", "ok2", "fail2", "ok3"}
	results, err := Process(context.Background(), inputs, 2,
		func(ctx context.Context, s string) (string, error) {
			if s[:4] == "fail" {
				return "", &customError{msg: s}
			}
			return s, nil
		})
	if err == nil {
		t.Fatal("expected aggregated error")
	}
	if len(results) != 3 {
		t.Fatalf("got %d results, want 3", len(results))
	}
	expected := []struct {
		idx    int
		output string
	}{
		{0, "ok1"},
		{2, "ok2"},
		{4, "ok3"},
	}
	for i, r := range results {
		if r.Index != expected[i].idx {
			t.Errorf("result %d: Index=%d, want %d", i, r.Index, expected[i].idx)
		}
		if r.Output != expected[i].output {
			t.Errorf("result %d: Output=%q, want %q", i, r.Output, expected[i].output)
		}
	}
	// Verify each individual failure is reachable.
	for _, in := range []string{"fail1", "fail2"} {
		if ce, ok := errors.AsType[*customError](err); !ok {
			t.Errorf("errors.AsType: customError not found: %v", err)
		} else if ce.msg != in {
			t.Errorf("errors.AsType: got %q, want %q", ce.msg, in)
		}
	}
}

func TestProcess_AllFailures(t *testing.T) {
	t.Parallel()
	inputs := []string{"x", "y", "z"}
	results, err := Process(context.Background(), inputs, 2,
		func(ctx context.Context, s string) (string, error) {
			return "", errSentinel
		})
	if err == nil {
		t.Fatal("expected aggregated error")
	}
	if len(results) != 0 {
		t.Fatalf("expected 0 results, got %d", len(results))
	}
	// errors.Is must work on the aggregated error for errSentinel.
	if !errors.Is(err, errSentinel) {
		t.Fatalf("errors.Is(err, errSentinel) failed on aggregated error: %v", err)
	}
}

func TestProcess_ContextCancellation(t *testing.T) {
	t.Parallel()
	ctx, cancel := context.WithCancel(context.Background())
	cancel() // immediately cancelled

	// Even though context is already cancelled, Process should run all
	// operations; each operation will see the cancelled context.
	inputs := []string{"a", "b", "c"}
	results, err := Process(ctx, inputs, 2,
		func(ctx context.Context, s string) (string, error) {
			return "", ctx.Err()
		})
	if err == nil {
		t.Fatal("expected aggregated error from cancelled context")
	}
	if len(results) != 0 {
		t.Fatalf("expected 0 results, got %d", len(results))
	}
	if !errors.Is(err, context.Canceled) {
		t.Fatalf("expected context.Canceled, got %v", err)
	}
}

func TestProcess_ConcurrencyLimit(t *testing.T) {
	t.Parallel()
	const concurrency = 3
	const totalInputs = 12

	var inFlight atomic.Int64
	var maxInFlight atomic.Int64

	results, err := Process(context.Background(), make([]string, totalInputs), concurrency,
		func(ctx context.Context, s string) (string, error) {
			n := inFlight.Add(1)
			defer inFlight.Add(-1)
			for prev := maxInFlight.Load(); n > prev; {
				if maxInFlight.CompareAndSwap(prev, n) {
					break
				}
				prev = maxInFlight.Load()
			}
			time.Sleep(10 * time.Millisecond) // ensure overlap
			return "ok", nil
		})
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(results) != totalInputs {
		t.Fatalf("got %d results, want %d", len(results), totalInputs)
	}
	if got := maxInFlight.Load(); got > int64(concurrency) {
		t.Fatalf("max concurrency was %d, want <= %d", got, concurrency)
	}
}

